  id:"johnday", name:"John Day River", color:"#a8552a",
  state:"OR", region:"oregon", gauges:["johndayBlueMtn","johndayJohnDay","johndayServiceCreek","johndayMcdonaldFerry"], primaryGauge:"johndayServiceCreek",
