  state:"IA", gauges:["wtDesMoinesFortDodge","wtDesMoinesStratford"], primaryGauge:"wtDesMoinesStratford",
  waterTrail:{name:"Des Moines River Water Trail", src:"Iowa DNR", designated:"2009-07-10", counties:["Webster","Boone"], miles:89.3, url:"https://www.iowadnr.gov/media/8886/download?inline"},
